For more information, see Creating origin request policies in the Amazon CloudFront Developer Guide . A complex type that specifies the Headers , if any, that you want CloudFront to forward to the origin for this cache behavior (whitelisted headers). For the headers that you specify, CloudFront also caches separate ver- sions of a specified object that is based on the header values in viewer requests. For more information, see Caching Content Based on Re- quest Headers in the Amazon CloudFront Developer Guide . Quantity -&gt; (integer) [required] The number of header names in the Items list. Items -&gt; (list) A list of HTTP header names. (string) QueryStringCacheKeys -&gt; (structure) This field is deprecated. We recommend that you use a cache policy or an origin request policy instead of this field. If you want to include query strings in the cache key, use a cache policy. For more information, see Creating cache policies in the Amazon CloudFront Developer Guide . If you want to send query strings to the origin but not include them in the cache key, use an origin request pol- icy. For more information, see Creating origin request policies in the Amazon CloudFront Developer Guide . A complex type that contains information about the query string parameters that you want CloudFront to use for caching for this cache behavior. Quantity -&gt; (integer) [required] The number of whitelisted query string parameters for a cache behavior. Items -&gt; (list) A list that contains the query string parameters that you want CloudFront to use as a basis for caching for a cache behavior. If Quantity is 0, you can omit Items . (string) MinTTL -&gt; (long) NOTE: This field only supports standard distributions. You can't specify this field for multi-tenant distributions. For more information, see Unsupported features for SaaS Manager for Amazon CloudFront in the Amazon CloudFront Developer Guide . This field is deprecated. We recommend that you use the MinTTL field in a cache policy instead of this field. For more information, see Creating cache policies or Using the managed cache policies in the Amazon CloudFront Developer Guide . The minimum amount of time that you want objects to stay in CloudFront caches before CloudFront forwards another request to your origin to determine whether the object has been up- dated. For more information, see Managing How Long Content Stays in an Edge Cache (Expiration) in the Amazon CloudFront Developer Guide . You must specify 0 for MinTTL if you configure CloudFront to forward all headers to your origin (under Headers , if you specify 1 for Quantity and * for Name ). DefaultTTL -&gt; (long) NOTE: This field only supports standard distributions. You can't specify this field for multi-tenant distributions. For more information, see Unsupported features for SaaS Manager for Amazon CloudFront in the Amazon CloudFront Developer Guide . This field is deprecated. We recommend that you use the De- faultTTL field in a cache policy instead of this field. For more information, see Creating cache policies or Using the managed cache policies in the Amazon CloudFront Developer Guide . The default amount of time that you want objects to stay in CloudFront caches before CloudFront forwards another request to your origin to determine whether the object has been up- dated. The value that you specify applies only when your ori- gin does not add HTTP headers such as Cache-Control max-age , Cache-Control s-maxage , and Expires to objects. For more in- formation, see Managing How Long Content Stays in an Edge Cache (Expiration) in the Amazon CloudFront Developer Guide . MaxTTL -&gt; (long) NOTE: This field only supports standard distributions. You can't specify this field for multi-tenant distributions. For more information, see Unsupported features for SaaS Manager for Amazon CloudFront in the Amazon CloudFront Developer Guide . This field is deprecated. We recommend that you use the MaxTTL field in a cache policy instead of this field. For more information, see Creating cache policies or Using the managed cache policies in the Amazon CloudFront Developer Guide . The maximum amount of time that you want objects to stay in CloudFront caches before CloudFront forwards another request to your origin to determine whether the object has been up- dated. The value that you specify applies only when your ori- gin adds HTTP headers such as Cache-Control max-age , Cache-Control s-maxage , and Expires to objects. For more in- formation, see Managing How Long Content Stays in an Edge Cache (Expiration) in the Amazon CloudFront Developer Guide . CacheBehaviors -&gt; (structure) A complex type that contains zero or more CacheBehavior ele- ments. Quantity -&gt; (integer) [required] The number of cache behaviors for this distribution. Items -&gt; (list) Optional: A complex type that contains cache behaviors for this distribution. If Quantity is 0 , you can omit Items . (structure) A complex type that describes how CloudFront processes requests. You must create at least as many cache behaviors (includ- ing the default cache behavior) as you have origins if you want CloudFront to serve objects from all of the ori- gins. Each cache behavior specifies the one origin from which you want CloudFront to get objects. If you have two origins and only the default cache behavior, the default cache behavior will cause CloudFront to get objects from one of the origins, but the other origin is never used. For the current quota (formerly known as limit) on the number of cache behaviors that you can add to a distribu- tion, see Quotas in the Amazon CloudFront Developer Guide . If you don't want to specify any cache behaviors, include only an empty CacheBehaviors element. Don't specify an empty individual CacheBehavior element, because this is invalid. For more information, see CacheBehaviors . To delete all cache behaviors in an existing distribu- tion, update the distribution configuration and include only an empty CacheBehaviors element. To add, change, or remove one or more cache behaviors, update the distribution configuration and specify all of the cache behaviors that you want to include in the up- dated distribution. WARNING: If your minimum TTL is greater than 0, CloudFront will cache content for at least the duration specified in the cache policy's minimum TTL, even if the Cache-Con- trol: no-cache , no-store , or private directives are present in the origin headers. For more information about cache behaviors, see Cache Be- havior Settings in the Amazon CloudFront Developer Guide . PathPattern -&gt; (string) [required] The pattern (for example, images/*.jpg ) that speci- fies which requests to apply the behavior to. When CloudFront receives a viewer request, the requested path is compared with path patterns in the order in which cache behaviors are listed in the distribution. NOTE: You can optionally include a slash (/ ) at the be- ginning of the path pattern. For example, /im- ages/*.jpg . CloudFront behavior is the same with or without the leading / . The path pattern for the default cache behavior is * and cannot be changed. If the request for an object does not match the path pattern for any cache behav- iors, CloudFront applies the behavior in the default cache behavior. For more information, see Path Pattern in the Amazon CloudFront Developer Guide . TargetOriginId -&gt; (string) [required] The value of ID for the origin that you want Cloud- Front to route requests to when they match this cache behavior. TrustedSigners -&gt; (structure) WARNING: We recommend using TrustedKeyGroups instead of TrustedSigners . NOTE: This field only supports standard distributions. You can't specify this field for multi-tenant dis- tributions. For more information, see Unsupported features for SaaS Manager for Amazon CloudFront in the Amazon CloudFront Developer Guide . A list of Amazon Web Services account IDs whose public keys CloudFront can use to validate signed URLs or signed cookies. When a cache behavior contains trusted signers, Cloud- Front requires signed URLs or signed cookies for all requests that match the cache behavior. The URLs or cookies must be signed with the private key of a CloudFront key pair in the trusted signer's Amazon Web Services account. The signed URL or cookie contains information about which public key CloudFront should use to verify the signature. For more information, see Serving private content in the Amazon CloudFront De- veloper Guide . Enabled -&gt; (boolean) [required] This field is true if any of the Amazon Web Ser- vices accounts in the list are configured as trusted signers. If not, this field is false . Quantity -&gt; (integer) [required] The number of Amazon Web Services accounts in the list. Items -&gt; (list) A list of Amazon Web Services account identifiers. (string) TrustedKeyGroups -&gt; (structure) A list of key groups that CloudFront can use to vali- date signed URLs or signed cookies. When a cache behavior contains trusted key groups, CloudFront requires signed URLs or signed cookies for all requests that match the cache behavior. The URLs or cookies must be signed with a private key whose corresponding public key is in the key group. The signed URL or cookie contains information about which public key CloudFront should use to verify the signa- ture. For more information, see Serving private con- tent in the Amazon CloudFront Developer Guide . Enabled -&gt; (boolean) [required] This field is true if any of the key groups in the list have public keys that CloudFront can use to verify the signatures of signed URLs and signed cookies. If not, this field is false . Quantity -&gt; (integer) [required] The number of key groups in the list. Items -&gt; (list) A list of key groups identifiers. (string) ViewerProtocolPolicy -&gt; (string) [required] The protocol that viewers can use to access the files in the origin specified by TargetOriginId when a re- quest matches the path pattern in PathPattern . You can specify the following options: o allow-all : Viewers can use HTTP or HTTPS. o redirect-to-https : If a viewer submits an HTTP re- quest, CloudFront returns an HTTP status code of 301 (Moved Permanently) to the viewer along with the HTTPS URL. The viewer then resubmits the request us- ing the new URL. o https-only : If a viewer sends an HTTP request, CloudFront returns an HTTP status code of 403 (For- bidden). For more information about requiring the HTTPS proto- col, see Requiring HTTPS Between Viewers and Cloud- Front in the Amazon CloudFront Developer Guide . NOTE: The only way to guarantee that viewers retrieve an object that was fetched from the origin using HTTPS is never to use any other protocol to fetch the object. If you have recently changed from HTTP to HTTPS, we recommend that you clear your ob- jects' cache because cached objects are protocol agnostic. That means that an edge location will return an object from the cache regardless of whether the current request protocol matches the protocol used previously. For more information, see Managing Cache Expiration in the Amazon Cloud- Front Developer Guide . Possible values: o allow-all o https-only o redirect-to-https AllowedMethods -&gt; (structure) A complex type that controls which HTTP methods Cloud- Front processes and forwards to your Amazon S3 bucket or your custom origin. There are three choices: o CloudFront forwards only GET and HEAD requests. o CloudFront forwards only GET , HEAD , and OPTIONS requests. o CloudFront forwards GET, HEAD, OPTIONS, PUT, PATCH, POST , and DELETE requests. If you pick the third choice, you may need to restrict access to your Amazon S3 bucket or to your custom ori- gin so users can't perform operations that you don't want them to. For example, you might not want users to have permissions to delete objects from your origin. Quantity -&gt; (integer) [required] The number of HTTP methods that you want Cloud- Front to forward to your origin. Valid values are 2 (for GET and HEAD requests), 3 (for GET , HEAD , and OPTIONS requests) and 7 (for GET, HEAD, OP- TIONS, PUT, PATCH, POST , and DELETE requests). Items -&gt; (list) [required] A complex type that contains the HTTP methods that you want CloudFront to process and forward to your origin. (string) Possible values: o GET o HEAD o POST o PUT o PATCH o OPTIONS o DELETE CachedMethods -&gt; (structure) A complex type that controls whether CloudFront caches the response to requests using the speci- fied HTTP methods. There are two choices: o CloudFront caches responses to GET and HEAD re- quests. o CloudFront caches responses to GET , HEAD , and OPTIONS requests. If you pick the second choice for your Amazon S3 Origin, you may need to forward Access-Control-Re- quest-Method, Access-Control-Request-Headers, and Origin headers for the responses to be cached cor- rectly. Quantity -&gt; (integer) [required] The number of HTTP methods for which you want CloudFront to cache responses. Valid values are 2 (for caching responses to GET and HEAD re- quests) and 3 (for caching responses to GET , HEAD , and OPTIONS requests). Items -&gt; (list) [required] A complex type that contains the HTTP methods that you want CloudFront to cache responses to. Valid values for CachedMethods include GET , HEAD , and OPTIONS , depending on which caching option you choose. For more information, see the preceding section. (string) Possible values: o GET o HEAD o POST o PUT o PATCH o OPTIONS o DELETE SmoothStreaming -&gt; (boolean) NOTE: This field only supports standard distributions. You can't specify this field for multi-tenant dis- tributions. For more information, see Unsupported features for SaaS Manager for Amazon CloudFront in the Amazon CloudFront Developer Guide . Indicates whether you want to distribute media files in the Microsoft Smooth Streaming format using the origin that is associated with this cache behavior. If so, specify true ; if not, specify false . If you specify true for SmoothStreaming , you can still dis- tribute other content using this cache behavior if the content matches the value of PathPattern . Compress -&gt; (boolean) Whether you want CloudFront to automatically compress certain files for this cache behavior. If so, specify true; if not, specify false. For more information, see Serving Compressed Files in the Amazon CloudFront De- veloper Guide . LambdaFunctionAssociations -&gt; (structure) A complex type that contains zero or more Lambda@Edge function associations for a cache behavior. Quantity -&gt; (integer) [required] The number of Lambda@Edge function associations for this cache behavior. Items -&gt; (list) Optional : A complex type that contains Lambda- FunctionAssociation items for this cache behav- ior. If Quantity is 0 , you can omit Items . (structure) A complex type that contains a Lambda@Edge function association. LambdaFunctionARN -&gt; (string) [required] The ARN of the Lambda@Edge function. You must specify the ARN of a function version; you can't specify an alias or $LATEST. EventType -&gt; (string) [required] Specifies the event type that triggers a Lambda@Edge function invocation. You can specify the following values: o viewer-request : The function executes when CloudFront receives a request from a viewer and before it checks to see whether the requested object is in the edge cache. o origin-request : The function executes only when CloudFront sends a request to your origin. When the requested object is in the edge cache, the function doesn't execute. o origin-response : The function executes after CloudFront receives a response from the origin and before it caches the ob- ject in the response. When the requested object is in the edge cache, the function doesn't execute. o viewer-response : The function executes before CloudFront returns the requested object to the viewer. The function exe- cutes regardless of whether the object was already in the edge cache. If the origin returns an HTTP status code other than HTTP 200 (OK), the function doesn't execute. Possible values: o viewer-request o viewer-response o origin-request o origin-response IncludeBody -&gt; (boolean) A flag that allows a Lambda@Edge function to have read access to the body content. For more information, see Accessing the Re- quest Body by Choosing the Include Body Op- tion in the Amazon CloudFront Developer Guide. FunctionAssociations -&gt; (structure) A list of CloudFront functions that are associated with this cache behavior. CloudFront functions must be published to the LIVE stage to associate them with a cache behavior. Quantity -&gt; (integer) [required] The number of CloudFront functions in the list. Items -&gt; (list) The CloudFront functions that are associated with a cache behavior in a CloudFront distribution. Your functions must be published to the LIVE stage to associate them with a cache behavior. (structure) A CloudFront function that is associated with a cache behavior in a CloudFront distribution. FunctionARN -&gt; (string) [required] The Amazon Resource Name (ARN) of the func- tion. Constraints: o min: 0 o max: 108 o pattern: arn:aws:cloud- front::[0-9]{12}:func- tion\/[a-zA-Z0-9-_]{1,64} EventType -&gt; (string) [required] The event type of the function, either viewer-request or viewer-response . You cannot use origin-facing event types (ori- gin-request and origin-response ) with a CloudFront function. Possible values: o viewer-request o viewer-response o origin-request o origin-response FieldLevelEncryptionId -&gt; (string) The value of ID for the field-level encryption config- uration that you want CloudFront to use for encrypting specific fields of data for this cache behavior. RealtimeLogConfigArn -&gt; (string) The Amazon Resource Name (ARN) of the real-time log configuration that is attached to this cache behavior. For more information, see Real-time logs in the Amazon CloudFront Developer Guide . CachePolicyId -&gt; (string) The unique identifier of the cache policy that is at- tached to this cache behavior. For more information, see Creating cache policies or Using the managed cache policies in the Amazon CloudFront Developer Guide . A CacheBehavior must include either a CachePolicyId or ForwardedValues . We recommend that you use a CacheP- olicyId . OriginRequestPolicyId -&gt; (string) The unique identifier of the origin request policy that is attached to this cache behavior. For more in- formation, see Creating origin request policies or Using the managed origin request policies in the Ama- zon CloudFront Developer Guide . ResponseHeadersPolicyId -&gt; (string) The identifier for a response headers policy. GrpcConfig -&gt; (structure) The gRPC configuration for your cache behavior. Enabled -&gt; (boolean) [required] Enables your CloudFront distribution to receive gRPC requests and to proxy them directly to your origins. ForwardedValues -&gt; (structure) This field is deprecated. We recommend that you use a cache policy or an origin request policy instead of this field. For more information, see Working with policies in the Amazon CloudFront Developer Guide . If you want to include values in the cache key, use a cache policy. For more information, see Creating cache policies or Using the managed cache policies in the Amazon CloudFront Developer Guide . If you want to send values to the origin but not in- clude them in the cache key, use an origin request policy. For more information, see Creating origin re- quest policies or Using the managed origin request policies in the Amazon CloudFront Developer Guide . A CacheBehavior must include either a CachePolicyId or ForwardedValues . We recommend that you use a CacheP- olicyId . A complex type that specifies how CloudFront handles query strings, cookies, and HTTP headers. QueryString -&gt; (boolean) [required] This field is deprecated. We recommend that you use a cache policy or an origin request policy in- stead of this field. If you want to include query strings in the cache key, use a cache policy. For more information, see Creating cache policies in the Amazon CloudFront Developer Guide . If you want to send query strings to the origin but not include them in the cache key, use an ori- gin request policy. For more information, see Creating origin request policies in the Amazon CloudFront Developer Guide . Indicates whether you want CloudFront to forward query strings to the origin that is associated with this cache behavior and cache based on the query string parameters. CloudFront behavior de- pends on the value of QueryString and on the val- ues that you specify for QueryStringCacheKeys , if any: If you specify true for QueryString and you don't specify any values for QueryStringCacheKeys , CloudFront forwards all query string parameters to the origin and caches based on all query string parameters. Depending on how many query string pa- rameters and values you have, this can adversely affect performance because CloudFront must forward more requests to the origin. If you specify true for QueryString and you spec- ify one or more values for QueryStringCacheKeys , CloudFront forwards all query string parameters to the origin, but it only caches based on the query string parameters that you specify. If you specify false for QueryString , CloudFront doesn't forward any query string parameters to the origin, and doesn't cache based on query string parameters. For more information, see Configuring CloudFront to Cache Based on Query String Parameters in the Amazon CloudFront Developer Guide . Cookies -&gt; (structure) [required] This field is deprecated. We recommend that you use a cache policy or an origin request policy in- stead of this field. If you want to include cookies in the cache key, use a cache policy. For more information, see Creating cache policies in the Amazon CloudFront Developer Guide . If you want to send cookies to the origin but not include them in the cache key, use an origin re- quest policy. For more information, see Creating origin request policies in the Amazon CloudFront Developer Guide . A complex type that specifies whether you want CloudFront to forward cookies to the origin and, if so, which ones. For more information about for- warding cookies to the origin, see How CloudFront Forwards, Caches, and Logs Cookies in the Amazon CloudFront Developer Guide . Forward -&gt; (string) [required] This field is deprecated. We recommend that you use a cache policy or an origin request policy instead of this field. If you want to include cookies in the cache key, use a cache policy. For more information, see Creating cache policies in the Amazon CloudFront Developer Guide . If you want to send cookies to the origin but not include them in the cache key, use origin request policy. For more information, see Creating origin request policies in the Amazon CloudFront Developer Guide . Specifies which cookies to forward to the ori- gin for this cache behavior: all, none, or the list of cookies specified in the Whitelisted- Names complex type. Amazon S3 doesn't process cookies. When the cache behavior is forwarding requests to an Amazon S3 origin, specify none for the Forward element. Possible values: o none o whitelist o all WhitelistedNames -&gt; (structure) This field is deprecated. We recommend that you use a cache policy or an origin request policy instead of this field. If you want to include cookies in the cache key, use a cache policy. For more information, see Creating cache policies in the Amazon CloudFront Developer Guide . If you want to send cookies to the origin but not include them in the cache key, use an ori- gin request policy. For more information, see Creating origin request policies in the Amazon CloudFront Developer Guide . Required if you specify whitelist for the value of Forward . A complex type that specifies how many different cookies you want CloudFront to forward to the origin for this cache behavior and, if you want to forward selected cookies, the names of those cookies. If you specify all or none for the value of Forward , omit WhitelistedNames . If you change the value of Forward from whitelist to all or none and you don't delete the WhitelistedNames element and its child elements, CloudFront deletes them automatically. For the current limit on the number of cookie names that you can whitelist for each cache be- havior, see CloudFront Limits in the Amazon Web Services General Reference . Quantity -&gt; (integer) [required] The number of cookie names in the Items list. Items -&gt; (list) A list of cookie names. (string) Headers -&gt; (structure) This field is deprecated. We recommend that you use a cache policy or an origin request policy in- stead of this field. If you want to include headers in the cache key, use a cache policy. For more information, see Creating cache policies in the Amazon CloudFront Developer Guide . If you want to send headers to the origin but not include them in the cache key, use an origin re- quest policy. For more information, see Creating origin request policies in the Amazon CloudFront Developer Guide . A complex type that specifies the Headers , if any, that you want CloudFront to forward to the origin for this cache behavior (whitelisted head- ers). For the headers that you specify, CloudFront also caches separate versions of a specified ob- ject that is based on the header values in viewer requests. For more information, see Caching Content Based on Request Headers in the Amazon CloudFront Developer Guide . Quantity -&gt; (integer) [required] The number of header names in the Items list. Items -&gt; (list) A list of HTTP header names. (string) QueryStringCacheKeys -&gt; (structure) This field is deprecated. We recommend that you use a cache policy or an origin request policy in- stead of this field. If you want to include query strings in the cache key, use a cache policy. For more information, see Creating cache policies in the Amazon CloudFront Developer Guide . If you want to send query strings to the origin but not include them in the cache key, use an ori- gin request policy. For more information, see Creating origin request policies in the Amazon CloudFront Developer Guide . A complex type that contains information about the query string parameters that you want CloudFront to use for caching for this cache behavior. Quantity -&gt; (integer) [required] The number of whitelisted query string parame- ters for a cache behavior. Items -&gt; (list) A list that contains the query string parame- ters that you want CloudFront to use as a basis for caching for a cache behavior. If Quantity is 0, you can omit Items . (string) MinTTL -&gt; (long) NOTE: This field only supports standard distributions. You can't specify this field for multi-tenant dis- tributions. For more information, see Unsupported features for SaaS Manager for Amazon CloudFront in the Amazon CloudFront Developer Guide . This field is deprecated. We recommend that you use the MinTTL field in a cache policy instead of this field. For more information, see Creating cache poli- cies or Using the managed cache policies in the Amazon CloudFront Developer Guide . The minimum amount of time that you want objects to stay in CloudFront caches before CloudFront forwards another request to your origin to determine whether the object has been updated. For more information, see Managing How Long Content Stays in an Edge Cache (Ex- piration) in the Amazon CloudFront Developer Guide . You must specify 0 for MinTTL if you configure Cloud- Front to forward all headers to your origin (under Headers , if you specify 1 for Quantity and * for Name ). DefaultTTL -&gt; (long) NOTE: This field only supports standard distributions. You can't specify this field for multi-tenant dis- tributions. For more information, see Unsupported features for SaaS Manager for Amazon CloudFront in the Amazon CloudFront Developer Guide . This field is deprecated. We recommend that you use the DefaultTTL field in a cache policy instead of this field. For more information, see Creating cache poli- cies or Using the managed cache policies in the Amazon CloudFront Developer Guide . The default amount of time that you want objects to stay in CloudFront caches before CloudFront forwards another request to your origin to determine whether the object has been updated. The value that you spec- ify applies only when your origin does not add HTTP headers such as Cache-Control max-age , Cache-Control s-maxage , and Expires to objects. For more informa- tion, see Managing How Long Content Stays in an Edge Cache (Expiration) in the Amazon CloudFront Developer Guide . MaxTTL -&gt; (long) NOTE: This field only supports standard distributions. You can't specify this field for multi-tenant dis- tributions. For more information, see Unsupported features for SaaS Manager for Amazon CloudFront in the Amazon CloudFront Developer Guide . This field is deprecated. We recommend that you use the MaxTTL field in a cache policy instead of this field. For more information, see Creating cache poli- cies or Using the managed cache policies in the Amazon CloudFront Developer Guide . The maximum amount of time that you want objects to stay in CloudFront caches before CloudFront forwards another request to your origin to determine whether the object has been updated. The value that you spec- ify applies only when your origin adds HTTP headers such as Cache-Control max-age , Cache-Control s-maxage , and Expires to objects. For more information, see Managing How Long Content Stays in an Edge Cache (Ex- piration) in the Amazon CloudFront Developer Guide . CustomErrorResponses -&gt; (structure) A complex type that controls the following: o Whether CloudFront replaces HTTP status codes in the 4xx and 5xx range with custom error messages before returning the re- sponse to the viewer. o How long CloudFront caches HTTP status codes in the 4xx and 5xx range. For more information about custom error pages, see Customizing Error Responses in the Amazon CloudFront Developer Guide . Quantity -&gt; (integer) [required] The number of HTTP status codes for which you want to specify a custom error page and/or a caching duration. If Quantity is 0 , you can omit Items . Items -&gt; (list) A complex type that contains a CustomErrorResponse element for each HTTP status code for which you want to specify a custom error page and/or a caching duration. (structure) A complex type that controls: o Whether CloudFront replaces HTTP status codes in the 4xx and 5xx range with custom error messages before re- turning the response to the viewer. o How long CloudFront caches HTTP status codes in the 4xx and 5xx range. For more information about custom error pages, see Customizing Error Responses in the Amazon CloudFront De- veloper Guide . ErrorCode -&gt; (integer) [required] The HTTP status code for which you want to specify a custom error page and/or a caching duration. ResponsePagePath -&gt; (string) The path to the custom error page that you want Cloud- Front to return to a viewer when your origin returns the HTTP status code specified by ErrorCode , for ex- ample, /4xx-errors/403-forbidden.html . If you want to store your objects and your custom error pages in dif- ferent locations, your distribution must include a cache behavior for which the following is true: o The value of PathPattern matches the path to your custom error messages. For example, suppose you saved custom error pages for 4xx errors in an Amazon S3 bucket in a directory named /4xx-errors . Your distribution must include a cache behavior for which the path pattern routes requests for your custom er- ror pages to that location, for example, /4xx-er- rors/* . o The value of TargetOriginId specifies the value of the ID element for the origin that contains your custom error pages. If you specify a value for ResponsePagePath , you must also specify a value for ResponseCode . We recommend that you store custom error pages in an Amazon S3 bucket. If you store custom error pages on an HTTP server and the server starts to return 5xx er- rors, CloudFront can't get the files that you want to return to viewers because the origin server is un- available. ResponseCode -&gt; (string) The HTTP status code that you want CloudFront to re- turn to the viewer along with the custom error page. There are a variety of reasons that you might want CloudFront to return a status code different from the status code that your origin returned to CloudFront, for example: o Some Internet devices (some firewalls and corporate proxies, for example) intercept HTTP 4xx and 5xx and prevent the response from being returned to the viewer. If you substitute 200 , the response typi- cally won't be intercepted. o If you don't care about distinguishing among differ- ent client errors or server errors, you can specify 400 or 500 as the ResponseCode for all 4xx or 5xx errors. o You might want to return a 200 status code (OK) and static website so your customers don't know that your website is down. If you specify a value for ResponseCode , you must also specify a value for ResponsePagePath . ErrorCachingMinTTL -&gt; (long) The minimum amount of time, in seconds, that you want CloudFront to cache the HTTP status code specified in ErrorCode . When this time period has elapsed, Cloud- Front queries your origin to see whether the problem that caused the error has been resolved and the re- quested object is now available. For more information, see Customizing Error Responses in the Amazon CloudFront Developer Guide . Comment -&gt; (string) [required] A comment to describe the distribution. The comment cannot be longer than 128 characters. Logging -&gt; (structure) A complex type that controls whether access logs are written for the distribution. For more information about logging, see Access Logs in the Ama- zon CloudFront Developer Guide . Enabled -&gt; (boolean) Specifies whether you want CloudFront to save access logs to an Amazon S3 bucket. If you don't want to enable logging when you create a distribution or if you want to disable logging for an existing distribution, specify false for Enabled , and specify empty Bucket and Prefix elements. If you specify false for Enabled but you specify values for Bucket and pre- fix , the values are automatically deleted. IncludeCookies -&gt; (boolean) Specifies whether you want CloudFront to include cookies in access logs, specify true for IncludeCookies . If you choose to include cookies in logs, CloudFront logs all cookies re- gardless of how you configure the cache behaviors for this distribution. If you don't want to include cookies when you create a distribution or if you want to disable include cook- ies for an existing distribution, specify false for Include- Cookies . Bucket -&gt; (string) The Amazon S3 bucket to store the access logs in, for exam- ple, amzn-s3-demo-bucket.s3.amazonaws.com . Prefix -&gt; (string) An optional string that you want CloudFront to prefix to the access log filenames for this distribution, for example, myprefix/ . If you want to enable logging, but you don't want to specify a prefix, you still must include an empty Prefix element in the Logging element. PriceClass -&gt; (string) NOTE: This field only supports standard distributions. You can't specify this field for multi-tenant distributions. For more information, see Unsupported features for SaaS Manager for Amazon CloudFront in the Amazon CloudFront Developer Guide . The price class that corresponds with the maximum price that you want to pay for CloudFront service. If you specify Price- Class_All , CloudFront responds to requests for your objects from all CloudFront edge locations. If you specify a price class other than PriceClass_All , Cloud- Front serves your objects from the CloudFront edge location that has the lowest latency among the edge locations in your price class. Viewers who are in or near regions that are excluded from your specified price class may encounter slower performance. For more information about price classes, see Choosing the Price Class for a CloudFront Distribution in the Amazon CloudFront De- veloper Guide . For information about CloudFront pricing, in- cluding how price classes (such as Price Class 100) map to CloudFront regions, see Amazon CloudFront Pricing . Possible values: o PriceClass_100 o PriceClass_200 o PriceClass_All o None Enabled -&gt; (boolean) [required] From this field, you can enable or disable the selected distrib- ution. ViewerCertificate -&gt; (structure) A complex type that determines the distribution's SSL/TLS con- figuration for communicating with viewers. CloudFrontDefaultCertificate -&gt; (boolean) If the distribution uses the CloudFront domain name such as d111111abcdef8.cloudfront.net , set this field to true . If the distribution uses Aliases (alternate domain names or CNAMEs), set this field to false and specify values for the following fields: o ACMCertificateArn or IAMCertificateId (specify a value for one, not both) o MinimumProtocolVersion o SSLSupportMethod IAMCertificateId -&gt; (string) NOTE: This field only supports standard distributions. You can't specify this field for multi-tenant distributions. For more information, see Unsupported features for SaaS Manager for Amazon CloudFront in the Amazon CloudFront Developer Guide . If the distribution uses Aliases (alternate domain names or CNAMEs) and the SSL/TLS certificate is stored in Identity and Access Management (IAM) , provide the ID of the IAM certifi- cate. If you specify an IAM certificate ID, you must also specify values for MinimumProtocolVersion and SSLSupportMethod . Constraints: o min: 0 o max: 32 ACMCertificateArn -&gt; (string) If the distribution uses Aliases (alternate domain names or CNAMEs) and the SSL/TLS certificate is stored in Certificate Manager (ACM) , provide the Amazon Resource Name (ARN) of the ACM certificate. CloudFront only supports ACM certificates in the US East (N. Virginia) Region (us-east-1 ). If you specify an ACM certificate ARN, you must also specify values for MinimumProtocolVersion and SSLSupportMethod . SSLSupportMethod -&gt; (string) If the distribution uses Aliases (alternate domain names or CNAMEs), specify which viewers the distribution accepts HTTPS connections from. o sni-only The distribution accepts HTTPS connections from only viewers that support server name indication (SNI) . This is recommended. Most browsers and clients support SNI. o vip The distribution accepts HTTPS connections from all viewers including those that don't support SNI. This is not recommended, and results in additional monthly charges from CloudFront. o static-ip - Do not specify this value unless your distribu- tion has been enabled for this feature by the CloudFront team. If you have a use case that requires static IP ad- dresses for a distribution, contact CloudFront through the Amazon Web ServicesSupport Center . If the distribution uses the CloudFront domain name such as d111111abcdef8.cloudfront.net , don't set a value for this field. Possible values: o sni-only o vip o static-ip MinimumProtocolVersion -&gt; (string) If the distribution uses Aliases (alternate domain names or CNAMEs), specify the security policy that you want CloudFront to use for HTTPS connections with viewers. The security pol- icy determines two settings: o The minimum SSL/TLS protocol that CloudFront can use to communicate with viewers. o The ciphers that CloudFront can use to encrypt the content that it returns to viewers. For more information, see Security Policy and Supported Pro- tocols and Ciphers Between Viewers and CloudFront in the Ama- zon CloudFront Developer Guide . NOTE: On the CloudFront console, this setting is called Secu- rity Policy . When you're using SNI only (you set SSLSupportMethod to sni-only ), you must specify TLSv1 or higher. If the distribution uses the CloudFront domain name such as d111111abcdef8.cloudfront.net (you set CloudFrontDefaultCer- tificate to true ), CloudFront automatically sets the secu- rity policy to TLSv1 regardless of the value that you set here. Possible values: o SSLv3 o TLSv1 o TLSv1_2016 o TLSv1.1_2016 o TLSv1.2_2018 o TLSv1.2_2019 o TLSv1.2_2021 o TLSv1.3_2025 o TLSv1.2_2025 Certificate -&gt; (string) This field is deprecated. Use one of the following fields in- stead: o ACMCertificateArn o IAMCertificateId o CloudFrontDefaultCertificate CertificateSource -&gt; (string) This field is deprecated. Use one of the following fields in- stead: o ACMCertificateArn o IAMCertificateId o CloudFrontDefaultCertificate Possible values: o cloudfront o iam o acm Restrictions -&gt; (structure) A complex type that identifies ways in which you want to re- strict distribution of your content. GeoRestriction -&gt; (structure) [required] A complex type that controls the countries in which your con- tent is distributed. CloudFront determines the location of your users using MaxMind GeoIP databases. RestrictionType -&gt; (string) [required] The method that you want to use to restrict distribution of your content by country: o none : No geo restriction is enabled, meaning access to content is not restricted by client geo location. o blacklist : The Location elements specify the countries in which you don't want CloudFront to distribute your content. o whitelist : The Location elements specify the countries in which you want CloudFront to distribute your con- tent. Possible values: o blacklist o whitelist o none Quantity -&gt; (integer) [required] When geo restriction is enabled , this is the number of countries in your whitelist or blacklist . Otherwise, when it is not enabled, Quantity is 0 , and you can omit Items . Items -&gt; (list) A complex type that contains a Location element for each country in which you want CloudFront either to distribute your content (whitelist ) or not distribute your content (blacklist ). The Location element is a two-letter, uppercase country code for a country that you want to include in your blacklist or whitelist . Include one Location element for each country. CloudFront and MaxMind both use ISO 3166 country codes. For the current list of countries and the corresponding codes, see ISO 3166-1-alpha-2 code on the International Organization for Standardization website. You can also refer to the country list on the CloudFront console, which includes both country names and codes. (string) WebACLId -&gt; (string) NOTE: Multi-tenant distributions only support WAF V2 web ACLs. A unique identifier that specifies the WAF web ACL, if any, to associate with this distribution. To specify a web ACL created using the latest version of WAF, use the ACL ARN, for example arn:aws:wafv2:us-east-1:123456789012:global/webacl/ExampleWe- bACL/a1b2c3d4-5678-90ab-cdef-EXAMPLE11111 . To specify a web ACL created using WAF Classic, use the ACL ID, for example a1b2c3d4-5678-90ab-cdef-EXAMPLE11111 . WAF is a web application firewall that lets you monitor the HTTP and HTTPS requests that are forwarded to CloudFront, and lets you control access to your content. Based on conditions that you specify, such as the IP addresses that requests originate from or the values of query strings, CloudFront responds to requests either with the requested content or with an HTTP 403 status code (Forbidden). You can also configure CloudFront to return a custom error page when a request is blocked. For more informa- tion about WAF, see the WAF Developer Guide . HttpVersion -&gt; (string) (Optional) Specify the HTTP version(s) that you want viewers to use to communicate with CloudFront. The default value for new web distributions is http2 . Viewers that don't support HTTP/2 automatically use an earlier HTTP version. For viewers and CloudFront to use HTTP/2, viewers must support TLSv1.2 or later, and must support Server Name Indication (SNI). For viewers and CloudFront to use HTTP/3, viewers must support TLSv1.3 and Server Name Indication (SNI). CloudFront supports HTTP/3 connection migration to allow the viewer to switch net- works without losing connection. For more information about con- nection migration, see Connection Migration at RFC 9000. For more information about supported TLSv1.3 ciphers, see Supported protocols and ciphers between viewers and CloudFront . Possible values: o http1.1 o http2 o http3 o http2and3 IsIPV6Enabled -&gt; (boolean) NOTE: To use this field for a multi-tenant distribution, use a con- nection group instead. For more information, see ConnectionGroup . If you want CloudFront to respond to IPv6 DNS requests with an IPv6 address for your distribution, specify true . If you spec- ify false , CloudFront responds to IPv6 DNS requests with the DNS response code NOERROR and with no IP addresses. This allows viewers to submit a second request, for an IPv4 address for your distribution. In general, you should enable IPv6 if you have users on IPv6 networks who want to access your content. However, if you're us- ing signed URLs or signed cookies to restrict access to your content, and if you're using a custom policy that includes the IpAddress parameter to restrict the IP addresses that can access your content, don't enable IPv6. If you want to restrict access to some content by IP address and not restrict access to other content (or restrict access but not by IP address), you can cre- ate two distributions. For more information, see Creating a Signed URL Using a Custom Policy in the Amazon CloudFront Devel- oper Guide . If you're using an Route 53 Amazon Web Services Integration alias resource record set to route traffic to your CloudFront distribution, you need to create a second alias resource record set when both of the following are true: o You enable IPv6 for the distribution o You're using alternate domain names in the URLs for your ob- jects For more information, see Routing Traffic to an Amazon Cloud- Front Web Distribution by Using Your Domain Name in the Route 53 Amazon Web Services Integration Developer Guide . If you created a CNAME resource record set, either with Route 53 Amazon Web Services Integration or with another DNS service, you don't need to make any changes. A CNAME record will route traf- fic to your distribution regardless of the IP address format of the viewer request. ContinuousDeploymentPolicyId -&gt; (string) NOTE: This field only supports standard distributions. You can't specify this field for multi-tenant distributions. For more information, see Unsupported features for SaaS Manager for Amazon CloudFront in the Amazon CloudFront Developer Guide . The identifier of a continuous deployment policy. For more in- formation, see CreateContinuousDeploymentPolicy . Staging -&gt; (boolean) NOTE: This field only supports standard distributions. You can't specify this field for multi-tenant distributions. For more information, see Unsupported features for SaaS Manager for Amazon CloudFront in the Amazon CloudFront Developer Guide . A Boolean that indicates whether this is a staging distribution. When this value is true , this is a staging distribution. When this value is false , this is not a staging distribution. AnycastIpListId -&gt; (string) NOTE: To use this field for a multi-tenant distribution, use a con- nection group instead. For more information, see ConnectionGroup . ID of the Anycast static IP list that is associated with the distribution. TenantConfig -&gt; (structure) NOTE: This field only supports multi-tenant distributions. You can't specify this field for standard distributions. For more information, see Unsupported features for SaaS Manager for Amazon CloudFront in the Amazon CloudFront Developer Guide . A distribution tenant configuration. ParameterDefinitions -&gt; (list) The parameters that you specify for a distribution tenant. (structure) A list of parameter values to add to the resource. A pa- rameter is specified as a key-value pair. A valid parame- ter value must exist for any parameter that is marked as required in the multi-tenant distribution. Name -&gt; (string) [required] The name of the parameter. Constraints: o min: 1 o max: 128 o pattern: [a-zA-Z0-9-_]+ Definition -&gt; (structure) [required] The value that you assigned to the parameter. StringSchema -&gt; (structure) An object that contains information about the string schema. Comment -&gt; (string) A comment to describe the parameter. DefaultValue -&gt; (string) The default value of the parameter. Constraints: o min: 1 o max: 256 Required -&gt; (boolean) [required] Whether the defined parameter is required. ConnectionMode -&gt; (string) This field specifies whether the connection mode is through a standard distribution (direct) or a multi-tenant distribution with distribution tenants (tenant-only). Possible values: o direct o tenant-only ViewerMtlsConfig -&gt; (structure) The distribution's viewer mTLS configuration. Mode -&gt; (string) The viewer mTLS mode. Possible values: o required o optional o passthrough TrustStoreConfig -&gt; (structure) The trust store configuration associated with the viewer mTLS configuration. TrustStoreId -&gt; (string) [required] The trust store ID. AdvertiseTrustStoreCaNames -&gt; (boolean) The configuration to use to advertise trust store CA names. IgnoreCertificateExpiry -&gt; (boolean) The configuration to use to ignore certificate expira- tion. ConnectionFunctionAssociation -&gt; (structure) The distribution's connection function association. Id -&gt; (string) [required] The association's ID. Constraints: o min: 1 o max: 64 CacheTagConfig -&gt; (structure) Configuration for cache tag extraction from origin responses. When specified, CloudFront reads the header named in HeaderName from origin responses and stores the comma-separated values as cache tags on the object. Distributions without CacheTagConfig do not extract tags. When CacheTagConfig is removed from a distribution via UpdateDistrib- ution , CloudFront stops extracting tags from origin responses. NOTE: Changing the HeaderName on an existing distribution does not retroactively affect previously cached objects. Tag-based in- validations will not apply to objects already cached using a previous header. To ensure tag invalidations function after updating the header name, use path-based invalidations to re- cache all objects that use cache tags. HeaderName -&gt; (string) [required] The name of the HTTP header that your origin includes in re- sponses. CloudFront uses this header to extract cache tags. The header value must contain comma-separated tag values (for example, product:electronics, category:tv, brand:example ). JSON Syntax: { "CallerReference": "string", "Aliases": { "Quantity": integer, "Items": ["string", ...] }, "DefaultRootObject": "string", "Origins": { "Quantity": integer, "Items": [ { "Id": "string", "DomainName": "string", "OriginPath": "string", "CustomHeaders": { "Quantity": integer, "Items": [ { "HeaderName": "string", "HeaderValue": "string" } ... ] }, "S3OriginConfig": { "OriginAccessIdentity": "string", "OriginReadTimeout": integer }, "CustomOriginConfig": { "HTTPPort": integer, "HTTPSPort": integer, "OriginProtocolPolicy": "http-only"|"match-viewer"|"https-only", "OriginSslProtocols": { "Quantity": integer, "Items": ["SSLv3"|"TLSv1"|"TLSv1.1"|"TLSv1.2", ...] }, "OriginReadTimeout": integer, "OriginKeepaliveTimeout": integer, "IpAddressType": "ipv4"|"ipv6"|"dualstack", "OriginMtlsConfig": { "ClientCertificateArn": "string" } }, "VpcOriginConfig": { "VpcOriginId": "string", "OwnerAccountId": "string", "OriginReadTimeout": integer, "OriginKeepaliveTimeout": integer }, "ConnectionAttempts": integer, "ConnectionTimeout": integer, "ResponseCompletionTimeout": integer, "OriginShield": { "Enabled": true|false, "OriginShieldRegion": "string" }, "OriginAccessControlId": "string" } ... ] }, "OriginGroups": { "Quantity": integer, "Items": [ { "Id": "string", "FailoverCriteria": { "StatusCodes": { "Quantity": integer, "Items": [integer, ...] } }, "Members": { "Quantity": integer, "Items": [ { "OriginId": "string" } ... ] }, "SelectionCriteria": "default"|"media-quality-based" } ... ] }, "DefaultCacheBehavior": { "TargetOriginId": "string", "TrustedSigners": { "Enabled": true|false, "Quantity": integer, "Items": ["string", ...] }, "TrustedKeyGroups": { "Enabled": true|false, "Quantity": integer, "Items": ["string", ...] }, "ViewerProtocolPolicy": "allow-all"|"https-only"|"redirect-to-https", "AllowedMethods": { "Quantity": integer, "Items": ["GET"|"HEAD"|"POST"|"PUT"|"PATCH"|"OPTIONS"|"DELETE", ...], "CachedMethods": { "Quantity": integer, "Items": ["GET"|"HEAD"|"POST"|"PUT"|"PATCH"|"OPTIONS"|"DELETE", ...] } }, "SmoothStreaming": true|false, "Compress": true|false, "LambdaFunctionAssociations": { "Quantity": integer, "Items": [ { "LambdaFunctionARN": "string", "EventType": "viewer-request"|"viewer-response"|"origin-request"|"origin-response", "IncludeBody": true|false } ... ] }, "FunctionAssociations": { "Quantity": integer, "Items": [ { "FunctionARN": "string", "EventType": "viewer-request"|"viewer-response"|"origin-request"|"origin-response" } ... ] }, "FieldLevelEncryptionId": "string", "RealtimeLogConfigArn": "string", "CachePolicyId": "string", "OriginRequestPolicyId": "string", "ResponseHeadersPolicyId": "string", "GrpcConfig": { "Enabled": true|false }, "ForwardedValues": { "QueryString": true|false, "Cookies": { "Forward": "none"|"whitelist"|"all", "WhitelistedNames": { "Quantity": integer, "Items": ["string", ...] } }, "Headers": { "Quantity": integer, "Items": ["string", ...] }, "QueryStringCacheKeys": { "Quantity": integer, "Items": ["string", ...] } }, "MinTTL": long, "DefaultTTL": long, "MaxTTL": long }, "CacheBehaviors": { "Quantity": integer, "Items": [ { "PathPattern": "string", "TargetOriginId": "string", "TrustedSigners": { "Enabled": true|false, "Quantity": integer, "Items": ["string", ...] }, "TrustedKeyGroups": { "Enabled": true|false, "Quantity": integer, "Items": ["string", ...] }, "ViewerProtocolPolicy": "allow-all"|"https-only"|"redirect-to-https", "AllowedMethods": { "Quantity": integer, "Items": ["GET"|"HEAD"|"POST"|"PUT"|"PATCH"|"OPTIONS"|"DELETE", ...], "CachedMethods": { "Quantity": integer, "Items": ["GET"|"HEAD"|"POST"|"PUT"|"PATCH"|"OPTIONS"|"DELETE", ...] } }, "SmoothStreaming": true|false, "Compress": true|false, "LambdaFunctionAssociations": { "Quantity": integer, "Items": [ { "LambdaFunctionARN": "string", "EventType": "viewer-request"|"viewer-response"|"origin-request"|"origin-response", "IncludeBody": true|false } ... ] }, "FunctionAssociations": { "Quantity": integer, "Items": [ { "FunctionARN": "string", "EventType": "viewer-request"|"viewer-response"|"origin-request"|"origin-response" } ... ] }, "FieldLevelEncryptionId": "string", "RealtimeLogConfigArn": "string", "CachePolicyId": "string", "OriginRequestPolicyId": "string", "ResponseHeadersPolicyId": "string", "GrpcConfig": { "Enabled": true|false }, "ForwardedValues": { "QueryString": true|false, "Cookies": { "Forward": "none"|"whitelist"|"all", "WhitelistedNames": { "Quantity": integer, "Items": ["string", ...] } }, "Headers": { "Quantity": integer, "Items": ["string", ...] }, "QueryStringCacheKeys": { "Quantity": integer, "Items": ["string", ...] } }, "MinTTL": long, "DefaultTTL": long, "MaxTTL": long } ... ] }, "CustomErrorResponses": { "Quantity": integer, "Items": [ { "ErrorCode": integer, "ResponsePagePath": "string", "ResponseCode": "string", "ErrorCachingMinTTL": long } ... ] }, "Comment": "string", "Logging": { "Enabled": true|false, "IncludeCookies": true|false, "Bucket": "string", "Prefix": "string" }, "PriceClass": "PriceClass_100"|"PriceClass_200"|"PriceClass_All"|"None", "Enabled": true|false, "ViewerCertificate": { "CloudFrontDefaultCertificate": true|false, "IAMCertificateId": "string", "ACMCertificateArn": "string", "SSLSupportMethod": "sni-only"|"vip"|"static-ip", "MinimumProtocolVersion": "SSLv3"|"TLSv1"|"TLSv1_2016"|"TLSv1.1_2016"|"TLSv1.2_2018"|"TLSv1.2_2019"|"TLSv1.2_2021"|"TLSv1.3_2025"|"TLSv1.2_2025", "Certificate": "string", "CertificateSource": "cloudfront"|"iam"|"acm" }, "Restrictions": { "GeoRestriction": { "RestrictionType": "blacklist"|"whitelist"|"none", "Quantity": integer, "Items": ["string", ...] } }, "WebACLId": "string", "HttpVersion": "http1.1"|"http2"|"http3"|"http2and3", "IsIPV6Enabled": true|false, "ContinuousDeploymentPolicyId": "string", "Staging": true|false, "AnycastIpListId": "string", "TenantConfig": { "ParameterDefinitions": [ { "Name": "string", "Definition": { "StringSchema": { "Comment": "string", "DefaultValue": "string", "Required": true|false } } } ... ] }, "ConnectionMode": "direct"|"tenant-only", "ViewerMtlsConfig": { "Mode": "required"|"optional"|"passthrough", "TrustStoreConfig": { "TrustStoreId": "string", "AdvertiseTrustStoreCaNames": true|false, "IgnoreCertificateExpiry": true|false } }, "ConnectionFunctionAssociation": { "Id": "string" }, "CacheTagConfig": { "HeaderName": "string" } }
    /// </summary>
    [CliOption("--distribution-config")]
    public string? DistributionConfig { get; set; }

